import {EFFECT_GROUPS} from './audio-effects.js';
import {MUSIC_OPTIONS,MUSIC_TRACKS,seasonMusicDefaults} from './music-catalog.js';
export function createContentAdmin(env){
 const {core:C,input,textarea,button:btn,icon:I,escape:esc,assetUrl,sceneAsset}=env;
 const select=(label,key,value,options)=>{
  const state=env.getState(),models=options.every(([id])=>state.catalog.some(r=>r.id===id)),scenes=options.every(([id])=>C.SCENES.includes(id));
  if(models||scenes){const visual=id=>models?env.sprite(state.catalog.find(r=>r.id===id)): `<img class="entity-scene" src="${assetUrl(sceneAsset(id))}" alt="">`,selected=options.find(([id])=>id===value)||options[0];
   return `<div class="form-field"><span>${esc(label)}</span><details class="entity-select"><summary>${visual(selected[0])}<b>${esc(selected[1])}</b>${I('chevron')}</summary><input type="hidden" name="${key}" value="${esc(selected[0])}"><div class="entity-options">${options.map(([id,name])=>`<button type="button" data-a="entity-choice" data-value="${esc(id)}">${visual(id)}<b>${esc(name)}</b>${I('chevron')}</button>`).join('')}</div></details></div>`;
  }
  return `<label class="form-field"><span>${esc(label)}</span><select name="${key}">${options.map(([id,name])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;
 };
 const toggle=(label,key,value)=>`<label class="checkbox"><input name="${key}" type="checkbox" ${value?'checked':''}>${esc(label)}</label>`;
 const copyLabels={homeTitle:'Título do hangar',storyTitle:'Título da campanha',storyDescription:'Descrição da campanha',arenaTitle:'Título da arena',arenaDescription:'Descrição da arena',shopTitle:'Título da oficina',shopDescription:'Descrição da oficina',robotsTitle:'Título da equipe',walletTitle:'Título da carteira',hangarLabel:'Botão Hangar',storyLabel:'Botão Aventura',arenaLabel:'Botão Arena',shopLabel:'Botão Oficina',walletLabel:'Botão Carteira',moreLabel:'Botão Mais',networkLabel:'Botão Rede',authTagline:'Frase da marca',authWorldText:'Mensagem do cenário de login',loginTitle:'Título de login',loginDescription:'Descrição de login',signupTitle:'Título de cadastro',signupDescription:'Descrição de cadastro'};
 const saveButton=label=>`<button class="btn primary" type="submit">${I('check')} ${label}</button>`;
 function renderSeasons(state){return `<div class="section-title"><h2>Temporadas (${C.seasons(state).length})</h2>${btn(I('plus')+' Nova temporada','edit-season','data-id="new"')}</div><div class="admin-catalog season-admin-list">${C.seasons(state).map(s=>`<article><span class="chapter-thumbnail"><img src="${assetUrl(sceneAsset(s.scene))}" alt="${esc(s.title)}"><span class="chapter-number">${String(s.number||1).padStart(2,'0')}</span></span><div><h3>${esc(s.title)}</h3><p>Capítulos ${s.from}–${s.to} · ${esc(s.subtitle)}</p><small>${I('volume')} ${esc(MUSIC_TRACKS[s.musicTheme]?.name||'Tema geral')} / ${esc(MUSIC_TRACKS[s.combatTheme]?.name||'Combate geral')}</small></div>${btn('Editar','edit-season',`data-id="${esc(s.id)}"`,'secondary')}</article>`).join('')}</div>`;}
 function render(tab){const state=env.getState(),s=state.settings;
  if(tab==='campaign')return `<form id="admin-story-settings" class="admin-form"><section><h3>${I('story')} Rejogar aventuras</h3><p>Primeira conclusão paga o prêmio uma vez. Um replay cobra a entrada ao iniciar, sem repetir o prêmio. A missão pode ser retomada após recarregar.</p><div class="form-grid">${input('Preço padrão do replay','replayCost',s.replayCost,'number','min="0" required')}${select('Moeda do replay','replayCurrency',s.replayCurrency,[['RC','RobotCoins'],['LC','LifeCoins']])}</div>${saveButton('Salvar regra de replay')}</section></form>${renderSeasons(state)}<div class="section-title"><h2>Capítulos (${C.chapters(state).length})</h2>${btn(I('plus')+' Novo capítulo','edit-chapter','data-id="new"')}</div><div class="admin-catalog chapter-admin-list">${C.chapters(state).map(c=>`<article><span class="chapter-thumbnail"><img src="${assetUrl(sceneAsset(c.scene))}" alt="${esc(c.place)}"><span class="chapter-number">${String(c.id).padStart(2,'0')}</span></span><div><h3>${esc(c.title)}</h3><p>${c.reward} RC · ${c.power} poder · ${c.enemies?.length||0} encontros</p><small>${esc(c.place)} · ${c.enabled===false?'Pausado':'Disponível'} · Replay ${c.replayCost??s.replayCost} ${c.replayCurrency||s.replayCurrency}</small></div>${btn('Editar','edit-chapter',`data-id="${c.id}"`,'secondary')}</article>`).join('')}</div>`;
  if(tab==='arena-config')return `<div class="notice">${I('arena')} Os adversários do jogo têm nomes próprios e atributos proporcionais ao robô do jogador. A busca prioriza usuários presentes quando o backend estiver conectado.</div><div class="section-title"><h2>Adversários (${state.arenaRoster.length})</h2>${btn(I('plus')+' Novo adversário','edit-rival','data-id="new"')}</div><div class="admin-catalog">${state.arenaRoster.map(r=>{const model=state.catalog.find(x=>x.id===r.robotId);return `<article>${env.sprite(model||state.catalog[0])}<div><h3>${esc(r.name)}</h3><p>${esc(model?.name)} · ${r.enabled===false?'Pausado':'Ativo'}</p><small>Ataque ×${r.attackFactor} · Defesa ×${r.defenseFactor} · Vida ×${r.healthFactor}</small></div>${btn('Editar','edit-rival',`data-id="${esc(r.id)}"`,'secondary')}</article>`;}).join('')}</div>`;
  if(tab==='combat')return `<form id="admin-combat" class="admin-form"><section><h3>${I('arena')} Combate, progressão e animações</h3><p>As alterações passam a valer em novos combates. Missões em andamento preservam suas regras.</p>${select('Controle padrão de novos encontros','defaultStoryControl',s.defaultStoryControl,[['auto','Combate automático'],['manual','Eu controlo']])}${toggle('Iniciar encontros automaticamente após a viagem','autoStoryStart',s.autoStoryStart)}<div class="form-grid">${C.RULE_FIELDS.map(([key,label,value,min,max])=>input(label,key,s.rules[key]??value,'number',`min="${min}" max="${max}" step="any" required`)).join('')}</div></section>${saveButton('Salvar regras do jogo')}</form>`;
  if(tab==='audio')return `<form id="admin-audio" class="admin-form"><section><h3>${I('volume')} Sons do universo</h3><div class="form-grid">${EFFECT_GROUPS.map(([key,label])=>env.mediaPicker('Arquivo: '+label,'effect_'+key,s.audio.customEffects?.[key]||'','audio')).join('')}</div><p>Quinze trilhas originais em estéreo. Cada temporada possui exploração e combate próprios, com transição suave. Motores, preparação, golpes, impactos, bloqueios e especiais acompanham as poses dos quinze modelos; efeitos de ataque, dano, defesa, especial, vitória, derrota, coleta, aquisição, montagem, evolução e notificações. Cada piloto pode ajustar ou desligar o áudio.</p><div class="audio-toggles">${toggle('Áudio disponível','enabled',s.audio.enabled)}${toggle('Música disponível','music',s.audio.music)}${toggle('Efeitos disponíveis','effects',s.audio.effects)}${toggle('Trocar trilha conforme a temporada da aventura','seasonMusic',s.audio.seasonMusic!==false)}</div><div class="form-grid">${select('Tema musical','theme',s.audio.theme,MUSIC_OPTIONS)}${select('Tema de combate','combatTheme',s.audio.combatTheme||'pulse',MUSIC_OPTIONS)}${env.mediaPicker('Trilha personalizada','customMusicUrl',s.audio.customMusicUrl||'','audio')}${env.mediaPicker('Trilha de combate','customCombatMusicUrl',s.audio.customCombatMusicUrl||'','audio')}${input('Ritmo (BPM)','tempo',s.audio.tempo,'number','min="40" max="180" required')}${input('Volume geral (0 a 1)','masterVolume',s.audio.masterVolume,'number','min="0" max="1" step="0.05" required')}${input('Volume da música (0 a 1)','musicVolume',s.audio.musicVolume,'number','min="0" max="1" step="0.05" required')}${input('Volume dos efeitos (0 a 1)','effectsVolume',s.audio.effectsVolume,'number','min="0" max="1" step="0.05" required')}${EFFECT_GROUPS.map(([key,label])=>input(label+' (0 a 1)',key,s.audio[key]??1,'number','min="0" max="1" step="0.05" required')).join('')}</div><div class="sound-cue-previews">${EFFECT_GROUPS.map(([,label,cue])=>btn(I('volume')+' '+label,'preview-sound',`data-id="${cue}"`,'secondary')).join('')}</div></section>${saveButton('Salvar áudio')}</form>`;
  if(tab==='copy')return `<form id="admin-copy" class="admin-form"><section><h3>${I('eye')} Títulos e navegação</h3><div class="form-grid">${Object.entries(s.copy).map(([key,value])=>input(copyLabels[key]||key,key,value,'text','maxlength="1000"')).join('')}</div></section><section><h3>Outros textos do jogo</h3><p>Para personalizar um texto adicional, informe o texto atual e o novo texto no mapa abaixo. Conteúdo é exibido como texto simples.</p>${textarea('Substituições de texto (JSON: "texto atual": "novo texto")','textOverrides',JSON.stringify(s.textOverrides||{},null,2))}<small>As indicações de moeda de teste e de adversário controlado pelo jogo permanecem visíveis.</small></section>${saveButton('Salvar textos')}</form>`;
  return '';
 }
 function editChapter(id){const state=env.getState(),fresh=id==='new',chapter=C.chapters(state).find(x=>x.id===Number(id))||{id:Math.max(0,...C.mainChapters(state).map(c=>c.id))+1,title:'Nova aventura',place:'Novo setor',story:'Uma nova transmissão pede ajuda.',reward:500,power:100,scene:'aurora',enabled:true,enemies:[{robotId:'moss',name:'Vigia do setor'},{robotId:'titan',name:'Guardião do setor'}]};
  const models=state.catalog.map(r=>[r.id,r.name]);
  env.modal(`<span class="eyebrow">CAPÍTULO ${chapter.id}</span><h2 id="modal-title">${fresh?'Nova aventura':'Editar aventura'}</h2><form id="chapter-form" data-id="${chapter.id}" data-fresh="${fresh}"><div class="form-grid">${select('Tipo de missão','chapterKind',chapter.chapterKind||'main',[['main','Trilha principal'],['side','Missão opcional']])}${select('Temporada','seasonId',chapter.seasonId||C.seasonForChapter(state,chapter.id)?.id||C.seasons(state)[0].id,C.seasons(state).map(s=>[s.id,s.title]))}${input('Opcional: liberar após capítulo','unlockChapter',chapter.unlockChapter||1,'number','min="1"')}${env.mediaPicker('Cenário deste capítulo','sceneArt',chapter.sceneArt||'')}${input('Título','title',chapter.title,'text','required maxlength="80"')}${input('Local','place',chapter.place,'text','required maxlength="100"')}${input('Poder necessário','power',chapter.power,'number','min="1" required')}${input('Prêmio único (RC)','reward',chapter.reward,'number','min="1" required')}${select('Cenário','scene',chapter.scene,C.SCENES.map(x=>[x,x]))}${input('Preço de replay: vazio usa padrão','replayCost',chapter.replayCost??'','number','min="0"')}${select('Moeda de replay','replayCurrency',chapter.replayCurrency||'',[['','Usar padrão'],['RC','RobotCoins'],['LC','LifeCoins']])}${input('Quantidade de encontros','waveCount',chapter.enemies.length,'number','min="1" max="8" required')}</div>${toggle('Fase disponível','enabled',chapter.enabled!==false)}${textarea('História e mensagem da viagem','story',chapter.story)}${textarea('Objetivo da missão','objective',chapter.objective||'Vença os guardiões e libere o sinal.')}${textarea('Mensagem após a vitória','conclusion',chapter.conclusion||'Um novo caminho se abriu.')}${textarea('Transmissões entre encontros: uma por linha','interludes',(chapter.interludes||[]).join('\n'))}<h3>Adversários de cada encontro</h3>${btn("+ Adicionar encontro","wave-add","","secondary")}<p>Valores vazios de ataque, defesa e vida usam as regras de dificuldade do painel.</p>${Array.from({length:8},(_,i)=>{const e=chapter.enemies[i]||{robotId:models[i%models.length][0],name:'Sentinela '+(i+1)};return `<details class="wave-editor" data-wave-index="${i}" ${i<chapter.enemies.length?'open':''}><summary>Encontro ${i+1}${i===chapter.enemies.length-1?' · Guardião':''}</summary><div class="form-grid">${btn("↑","wave-up",`data-id="${i}"`,"secondary")}${btn("↓","wave-down",`data-id="${i}"`,"secondary")}${btn("Remover","wave-remove",`data-id="${i}"`,"text")}${select('Robô','wave'+i+'Robot',e.robotId,models)}${input('Nome','wave'+i+'Name',e.name,'text','maxlength="60"')}${['attack','defense','health'].map(k=>input({attack:'Ataque',defense:'Defesa',health:'Vida'}[k],'wave'+i+k,e[k]??'','number',`min="${k==='defense'?0:1}"`)).join('')}</div></details>`;}).join('')}${saveButton('Salvar capítulo')}</form>`,'large');
 }
 function editRival(id){const state=env.getState(),r=state.arenaRoster.find(x=>x.id===id)||{id:'new',name:'Novo guardião',robotId:state.catalog[0].id,attackFactor:.95,defenseFactor:.9,healthFactor:1,enabled:true};
  env.modal(`<h2 id="modal-title">Adversário da arena</h2><form id="rival-form" data-id="${esc(r.id)}"><div class="form-grid">${input('Nome de batalha','name',r.name,'text','required maxlength="40"')}${select('Robô','robotId',r.robotId,state.catalog.map(m=>[m.id,m.name]))}${['attackFactor','defenseFactor','healthFactor'].map(k=>input({attackFactor:'Ataque proporcional',defenseFactor:'Defesa proporcional',healthFactor:'Vida proporcional'}[k],k,r[k],'number','min="0.25" max="2" step="0.01" required')).join('')}</div>${toggle('Disponível na arena','enabled',r.enabled!==false)}${saveButton('Salvar adversário')}</form>`);
 }
 function editSeason(id){const state=env.getState(),last=Math.max(0,...C.seasons(state).map(s=>s.to)),season=C.seasons(state).find(s=>s.id===id)||{id:'new',number:C.seasons(state).length+1,title:'Nova temporada',subtitle:'Uma nova transmissão.',intro:'Explore os novos setores e restaure os sinais.',from:last+1,to:last+6,scene:'aurora',guideRobotId:state.catalog[0].id,...seasonMusicDefaults('aurora')};
  env.modal(`<h2 id="modal-title">Temporada da campanha</h2><p>Defina a temporada e depois adicione seus capítulos, inimigos e prêmios. Os intervalos de temporadas devem ser distintos.</p><form id="season-form" data-id="${esc(season.id)}"><div class="form-grid">${input('Título','title',season.title,'text','required maxlength="100"')}${input('Frase da temporada','subtitle',season.subtitle,'text','required maxlength="150"')}${input('Número da temporada','number',season.number,'number','min="1" required')}${input('Primeiro capítulo','from',season.from,'number','min="1" required')}${input('Último capítulo','to',season.to,'number','min="1" required')}${select('Cenário','scene',season.scene,C.SCENES.map(x=>[x,x]))}${select('Robô do guia','guideRobotId',season.guideRobotId,state.catalog.map(r=>[r.id,r.name]))}${select('Trilha de exploração','musicTheme',season.musicTheme||'',[['','Usar tema geral'],...MUSIC_OPTIONS])}${select('Trilha das batalhas','combatTheme',season.combatTheme||'',[['','Usar combate geral'],...MUSIC_OPTIONS])}${input('Ritmo da exploração (BPM)','musicTempo',season.musicTempo||MUSIC_TRACKS[season.musicTheme]?.bpm||96,'number','min="40" max="180" required')}${input('Ritmo das batalhas (BPM)','combatTempo',season.combatTempo||MUSIC_TRACKS[season.combatTheme]?.bpm||112,'number','min="40" max="180" required')}${env.mediaPicker('Exploração: música própria','customMusicUrl',season.customMusicUrl||'','audio')}${env.mediaPicker('Batalhas: música própria','customCombatMusicUrl',season.customCombatMusicUrl||'','audio')}${env.mediaPicker('Arte da temporada','sceneArt',season.sceneArt||'')}</div>${textarea('Mensagem e história do guia','intro',season.intro)}${saveButton('Salvar temporada')}</form>`,'large');
 }
 async function submit(form,v){const current=env.getState(),s=current.settings;
  if(form.id==='admin-story-settings'){const next={...s,replayCost:Number(v.replayCost),replayCurrency:v.replayCurrency};C.validateSettings(next);await env.mutate(state=>state.settings=next,'Regra de replay salva.',{action:'admin_save',payload:{settings:next}});}
  else if(form.id==='admin-combat'){const next={...s,autoStoryStart:v.autoStoryStart==='on',defaultStoryControl:v.defaultStoryControl||'auto',rules:Object.fromEntries(C.RULE_FIELDS.map(([key])=>[key,Number(v[key])]))};C.validateSettings(next);await env.mutate(state=>{C.collect(state);state.settings=next;},'Regras do jogo atualizadas.',{action:'admin_save',payload:{settings:next}});}
  else if(form.id==='admin-audio'){const audio={...s.audio,...v,enabled:v.enabled==='on',music:v.music==='on',effects:v.effects==='on',seasonMusic:v.seasonMusic==='on'};for(const key of ['tempo','masterVolume','musicVolume','effectsVolume',...EFFECT_GROUPS.map(([key])=>key)])audio[key]=Number(v[key]);audio.customEffects={...s.audio.customEffects};for(const [key] of EFFECT_GROUPS)if(v['effect_'+key]!==undefined)audio.customEffects[key]=v['effect_'+key];for(const key of Object.keys(audio))if(key.startsWith('effect_'))delete audio[key];const next={...s,audio};C.validateSettings(next);await env.mutate(state=>state.settings=next,'Áudio atualizado.',{action:'admin_save',payload:{settings:next}});env.audio.refresh();}
  else if(form.id==='admin-copy'){const {textOverrides,...copy}=v;const next={...s,copy:{...s.copy,...copy},textOverrides:JSON.parse(textOverrides||'{}')};C.validateSettings(next);await env.mutate(state=>state.settings=next,'Textos atualizados.',{action:'admin_save',payload:{settings:next}});}
  else if(form.id==='chapter-form'){const count=Number(v.waveCount);if(!Number.isSafeInteger(count)||count<1||count>8)throw new Error('Use entre 1 e 8 encontros.');const chapter={id:form.dataset.fresh==='true'&&v.chapterKind==='side'?Math.max(1000,...C.chapters(current).filter(c=>c.chapterKind==='side').map(c=>c.id))+1:Number(form.dataset.id),title:v.title.trim(),place:v.place.trim(),story:v.story,objective:v.objective,conclusion:v.conclusion,interludes:(v.interludes||'').split('\n').filter(Boolean),power:Number(v.power),reward:Number(v.reward),scene:v.scene,sceneArt:v.sceneArt||'',chapterKind:v.chapterKind||C.chapters(current).find(c=>c.id===Number(form.dataset.id))?.chapterKind||'main',seasonId:v.seasonId||C.chapters(current).find(c=>c.id===Number(form.dataset.id))?.seasonId,unlockChapter:Number(v.unlockChapter||C.chapters(current).find(c=>c.id===Number(form.dataset.id))?.unlockChapter||0),enabled:v.enabled==='on',replayCost:v.replayCost===''?null:Number(v.replayCost),replayCurrency:v.replayCurrency||null,enemies:Array.from({length:count},(_,i)=>{const wave={robotId:v['wave'+i+'Robot'],name:(v['wave'+i+'Name']||'').trim()};for(const k of ['attack','defense','health'])if(v['wave'+i+k]!==''&&v['wave'+i+k]!=null)wave[k]=Number(v['wave'+i+k]);return wave;})};C.validateChapter(current,chapter);await env.mutate(state=>C.saveChapter(state,chapter),'Aventura atualizada.',{action:'admin_save',payload:{chapter}});}
  else if(form.id==='rival-form'){const rival={id:form.dataset.id==='new'?C.uuid():form.dataset.id,name:v.name.trim(),robotId:v.robotId,enabled:v.enabled==='on',attackFactor:Number(v.attackFactor),defenseFactor:Number(v.defenseFactor),healthFactor:Number(v.healthFactor)};const roster=current.arenaRoster.filter(x=>x.id!==rival.id).concat(rival);C.validateArenaRoster(current,roster);await env.mutate(state=>state.arenaRoster=roster,'Adversário atualizado.',{action:'admin_save',payload:{arenaRoster:roster}});}
  else if(form.id==='season-form'){const season={id:form.dataset.id==='new'?C.uuid():form.dataset.id,title:v.title.trim(),subtitle:v.subtitle.trim(),intro:v.intro,number:Number(v.number),from:Number(v.from),to:Number(v.to),scene:v.scene,guideRobotId:v.guideRobotId,musicTheme:v.musicTheme||'',combatTheme:v.combatTheme||'',musicTempo:Number(v.musicTempo),combatTempo:Number(v.combatTempo),customMusicUrl:v.customMusicUrl||'',customCombatMusicUrl:v.customCombatMusicUrl||'',sceneArt:v.sceneArt||''};const trial=C.clone(current);C.saveSeason(trial,season);await env.mutate(state=>C.saveSeason(state,season),'Temporada atualizada.',{action:'admin_save',payload:{season}});}
  else return false;return true;
 }
 function syncWaves(form){const count=Number(form.querySelector('[name=waveCount]')?.value||1);form.querySelectorAll('[data-wave-index]').forEach(el=>{el.hidden=Number(el.dataset.waveIndex)>=count;});}
 function wave(action,index){const form=document.querySelector('#chapter-form');if(!form)return;const countInput=form.querySelector('[name=waveCount]'),count=Number(countInput.value),swap=(a,b)=>{for(const key of ['Robot','Name','attack','defense','health']){const x=form.querySelector(`[name=wave${a}${key}]`),y=form.querySelector(`[name=wave${b}${key}]`);[x.value,y.value]=[y.value,x.value];}};if(action==='wave-add')countInput.value=Math.min(8,count+1);if(action==='wave-up'&&index>0)swap(index,index-1);if(action==='wave-down'&&index<count-1)swap(index,index+1);if(action==='wave-remove'&&count>1){for(let i=index;i<count-1;i++)swap(i,i+1);countInput.value=count-1;}syncWaves(form);}
 return {wave,syncWaves,render,editChapter,editRival,editSeason,submit,handles:tab=>['campaign','arena-config','combat','audio','copy'].includes(tab)};
}
